// The named fixtures of criterion 45 (the TUNING corpus), generated by test code from small invented logical datasets. Each
// fixture carries its ground-truth mapping (per column, in file order) and its golden canonical CSV (the canonical headers
// in schema order, dot decimals, ISO dates, canonical statuses and warehouse codes). Nothing is downloaded; every company,
// person and identifier is invented.

import { concat, cp1252, utf16le, utf8, utf8Bom } from '../../ingest-kit/corpus';
import { formatCents, formatDate, STATUS_WORDS, type DateStyle, type NumberStyle } from './gen';

export type Kind = 'inventory' | 'shipments';
export type LogicalRow = Record<string, string>;

const INVENTORY_FIELDS = ['sku', 'product_name', 'category', 'warehouse', 'quantity', 'reorder_point', 'unit_cost', 'avg_daily_usage', 'lead_time_days'];
const SHIPMENT_FIELDS = ['shipment_id', 'origin', 'destination', 'carrier', 'status', 'ship_date', 'estimated_delivery', 'actual_delivery', 'shipping_cost'];
export const CANONICAL_FIELDS: Record<Kind, string[]> = { inventory: INVENTORY_FIELDS, shipments: SHIPMENT_FIELDS };

const PRODUCTS = ['Wireless Barcode Scanner', 'Label Printer', 'Pallet Wrap Film', 'Corrugated Box 12x12x12', 'Safety Gloves', 'Thermal Labels', 'Packing Tape', 'Forklift Battery', 'Shelf Bracket', 'Hand Truck'];
const CATEGORIES = ['Electronics', 'Packaging', 'Safety', 'Hardware', 'Labels', 'Equipment'];
const CARRIERS = ['Northstar Freight', 'BlueLine Logistics', 'Cascade Carriers', 'Summit Express', 'Redwood Transport'];
const CITIES = ['Houston, TX', 'San Antonio, TX', 'Phoenix, AZ', 'Denver, CO', 'Kansas City, MO', 'Nashville, TN', 'Miami, FL', 'Charlotte, NC'];
const WH = ['WH-DFW', 'WH-ATL', 'WH-ORD', 'WH-LAX', 'WH-EWR'];
const STATUSES = ['delivered', 'in_transit', 'pending', 'cancelled'];

const money = (cents: number): string => `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
const iso = (day: number): string => `2026-03-${String(day).padStart(2, '0')}`;

export function inventoryRows(n = 12): LogicalRow[] {
  return Array.from({ length: n }, (_, i) => ({
    sku: `ELC-${9001 + i * 2}`,
    product_name: `${PRODUCTS[i % PRODUCTS.length]}`,
    category: CATEGORIES[i % CATEGORIES.length] as string,
    warehouse: WH[i % WH.length] as string,
    quantity: String(20 + ((i * 37) % 900)),
    reorder_point: String(10 + ((i * 13) % 120)),
    unit_cost: money(850 + ((i * 1373 + 251) % 150000)),
    avg_daily_usage: money(150 + ((i * 97) % 2000)),
    lead_time_days: String(2 + ((i * 5) % 40))
  }));
}

export function shipmentRows(n = 12): LogicalRow[] {
  return Array.from({ length: n }, (_, i) => {
    const status = STATUSES[i % 4] as string;
    const day = 1 + ((i * 2) % 20);
    return {
      shipment_id: `SHP-${900001 + i * 3}`,
      origin: WH[i % WH.length] as string,
      destination: CITIES[(i + 1) % CITIES.length] as string,
      carrier: CARRIERS[i % CARRIERS.length] as string,
      status,
      ship_date: iso(day),
      estimated_delivery: iso(day + 3),
      actual_delivery: status === 'delivered' ? iso(day + 2 + (i % 3)) : '',
      shipping_cost: money(40000 + ((i * 7919) % 120000))
    };
  });
}

export type Encoding = 'utf8' | 'utf8bom' | 'utf16le' | 'cp1252';

export interface RenderSpec {
  headers: Record<string, string>;
  /** Field order in the file (default: schema order). Fields absent here are omitted from the file. */
  order?: string[];
  delimiter: string;
  numberStyle: NumberStyle;
  dateStyle: DateStyle;
  statusWords: keyof typeof STATUS_WORDS | string[];
  encoding: Encoding;
  banner?: string[];
  totalRow?: string[];
  extra?: Array<{ header: string; values: (i: number) => string }>;
  warehouseStyle?: 'code' | 'name' | 'plant';
  eol?: '\n' | '\r\n';
}

export interface Fixture {
  name: string;
  kind: Kind;
  bytes: Uint8Array;
  hints: { fileName: string; extension: string };
  /** The user confirmations the file needs to be read (encoding confirmation). */
  options: Record<string, string>;
  /** Per column of the header row, in file order: the canonical field a person would choose, or null. */
  truth: Array<string | null>;
  headers: string[];
  logical: LogicalRow[];
  /** Golden canonical CSV of the logical rows (all canonical columns, schema order). */
  golden: string;
  /** Status words as written in the file, with their canonical meaning. */
  statusMap: Array<[word: string, status: string]>;
  /** Warehouse values as written, for files whose warehouses are not the known codes. */
  warehouseMap?: Array<[value: string, code: string]>;
  numberStyle: NumberStyle;
  dateStyle: DateStyle;
  text: string;
}

function quoteIfNeeded(value: string, delimiter: string): string {
  return value.includes(delimiter) || value.includes('"') || value.includes('\n') ? `"${value.replace(/"/g, '""')}"` : value;
}

function styled(field: string, kind: Kind, value: string, spec: RenderSpec, rowIndex: number): string {
  if (value === '') return '';
  if (field === 'unit_cost' || field === 'shipping_cost' || field === 'avg_daily_usage') return formatCents(Number(value.replace('.', '')), spec.numberStyle);
  if (field === 'ship_date' || field === 'estimated_delivery' || field === 'actual_delivery') {
    const [y, m, d] = value.split('-').map(Number) as [number, number, number];
    return formatDate(y, m, d, spec.dateStyle);
  }
  if (field === 'status') {
    const words = Array.isArray(spec.statusWords) ? spec.statusWords : (STATUS_WORDS[spec.statusWords] as readonly string[]);
    return words[STATUSES.indexOf(value)] as string;
  }
  if (field === 'warehouse' && kind === 'inventory') {
    if (spec.warehouseStyle === 'plant') return ['1000', '1010', '2000', '3000', '3010'][WH.indexOf(value)] as string;
    return value;
  }
  void rowIndex;
  return value;
}

export function canonicalCsv(kind: Kind, rows: LogicalRow[]): string {
  const cols = CANONICAL_FIELDS[kind];
  return [cols.join(','), ...rows.map((r) => cols.map((c) => quoteIfNeeded(r[c] ?? '', ',')).join(','))].join('\n') + '\n';
}

function encode(text: string, encoding: Encoding): Uint8Array {
  switch (encoding) {
    case 'utf8':
      return utf8(text);
    case 'utf8bom':
      return utf8Bom(text);
    case 'utf16le':
      return utf16le(text);
    case 'cp1252':
      return cp1252(text);
  }
}

export function makeFixture(name: string, kind: Kind, logical: LogicalRow[], spec: RenderSpec): Fixture {
  const order = spec.order ?? CANONICAL_FIELDS[kind];
  const eol = spec.eol ?? '\n';
  const headers = [...order.map((f) => spec.headers[f] as string), ...(spec.extra ?? []).map((e) => e.header)];
  const truth: Array<string | null> = [...order, ...(spec.extra ?? []).map(() => null)];
  const lines: string[] = [];
  for (const b of spec.banner ?? []) lines.push(b);
  lines.push(headers.map((h) => quoteIfNeeded(h, spec.delimiter)).join(spec.delimiter));
  logical.forEach((row, i) => {
    const cells = [...order.map((f) => styled(f, kind, row[f] ?? '', spec, i)), ...(spec.extra ?? []).map((e) => e.values(i))];
    lines.push(cells.map((c) => quoteIfNeeded(c, spec.delimiter)).join(spec.delimiter));
  });
  if (spec.totalRow !== undefined) lines.push(spec.totalRow.join(spec.delimiter));
  const text = lines.join(eol) + eol;
  const extension = spec.delimiter === '\t' ? '.tsv' : '.csv';
  const words = Array.isArray(spec.statusWords) ? spec.statusWords : (STATUS_WORDS[spec.statusWords] as readonly string[]);
  const statusMap: Array<[string, string]> = words.map((w, i) => [w, STATUSES[i] as string]);
  const plantMap: Array<[string, string]> | undefined =
    spec.warehouseStyle === 'plant' ? [['1000', 'WH-DFW'], ['1010', 'WH-ATL'], ['2000', 'WH-ORD'], ['3000', 'WH-LAX'], ['3010', 'WH-EWR']] : undefined;
  const fixture: Fixture = {
    name,
    kind,
    bytes: encode(text, spec.encoding),
    hints: { fileName: name, extension },
    options: spec.encoding === 'cp1252' ? { encoding: 'windows-1252' } : {},
    truth,
    headers,
    logical,
    // fields the file does not carry are emitted as empty columns by the canonical builder (policy 5.3)
    golden: canonicalCsv(kind, logical.map((row) => Object.fromEntries(CANONICAL_FIELDS[kind].map((c) => [c, order.includes(c) ? (row[c] ?? '') : ''])))),
    statusMap,
    numberStyle: spec.numberStyle,
    dateStyle: spec.dateStyle,
    text
  };
  if (plantMap !== undefined) fixture.warehouseMap = plantMap;
  return fixture;
}

