export function fixtureByName(name: string): Fixture {
  const f = [...FIXTURES, ...AMBIGUITY_FIXTURES].find((x) => x.name === name);
  if (f === undefined) throw new Error(`unknown fixture ${name}`);
  return f;
}

// ---- ambiguity and structure fixtures (no golden canonical output unless stated) -------------------------------------------------

const textFixture = (name: string, kind: Kind, text: string, truth: Array<string | null>, encoding: Encoding = 'utf8'): Fixture => ({
  name,
  kind,
  bytes: encode(text, encoding),
  hints: { fileName: name, extension: name.endsWith('.tsv') ? '.tsv' : '.csv' },
  options: {},
  truth,
  headers: (text.split('\n')[0] as string).split(','),
  logical: [],
  golden: '',
  statusMap: [],
  numberStyle: 'plain',
  dateStyle: 'iso',
  text
});

